import csv

# Read driver standings
driver_standings = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        driver_standings.append(row)

# Read races
races = {}
with open('csv/races.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        races[row['raceId']] = row

# Find races where Alex Yoong (driverId=62) participated with round < 20
yoong_races = []
for ds in driver_standings:
    if ds['driverId'] == '62':
        race_id = ds['raceId']
        if race_id in races:
            race = races[race_id]
            if int(race['round']) < 20:
                yoong_races.append({'raceName': race['name'], 'round': race['round'], 'year': race['year']})

print(f"Found {len(yoong_races)} races")
for r in yoong_races[:10]:
    print(r)

